contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(c.balances(address(this)) == 0);
        require(c.MinSum() == 0);

        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        assert(
            beforeBal == 0 &&
            afterBal == beforeBal &&
            afterContractBalance == beforeContractBalance &&
            afterThisBalance == beforeThisBalance
        );
    }

    receive() external payable {}
}

