    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(c.balances(address(this)) == 0);
        vm.assume(c.MinSum() == 0);
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterContractBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        assertTrue(beforeBal == 0 &&
            afterBal == beforeBal &&
            afterContractBalance == beforeContractBalance &&
            afterThisBalance == beforeThisBalance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

